"""Small synthetic session in the data-standard layout, for trying the pipeline
(and for the tests) without real data. ``uv run cclab-preproc make-demo``."""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd
import scipy.io as sio

DEMO_CONFIG = """\
# Demo session generated by `cclab-preproc make-demo` (synthetic data).
[session]
animal = "venni"
date = "20250731"
area = "SEF"
probe = "npx"

[[tasks]]
name = "mgs"
spikeglx_run = "MGS1"

[[tasks]]
name = "FV"
spikeglx_run = "FV1"

[catgt]
probes = "0"

[meta]
task = "mgs"
behavior_file = "raw/behavior/remgs1.mat"
"""


def make_demo(data_root: Path, n_units: int = 12, n_trials: int = 80, seed: int = 0) -> Path:
    """Write a synthetic session under ``data_root`` and return the config path."""
    rng = np.random.default_rng(seed)
    sr = 30000
    task_dir = Path(data_root) / "neuropixel" / "venni" / "venni_20250731_SEF" / "mgs"
    ks = task_dir / "processed" / "kilosort4"
    ev = task_dir / "processed" / "events"
    beh = task_dir / "raw" / "behavior"
    for d in (ks, ev, beh, task_dir / "raw" / "MGS1_g0", task_dir.parent / "FV" / "raw" / "FV1_g0"):
        d.mkdir(parents=True, exist_ok=True)

    # behavior: attempted trials only are aligned; add a few non-attempts
    n_rows = n_trials + 5
    attempt = np.ones(n_rows)
    attempt[rng.choice(n_rows, 5, replace=False)] = 0
    angles = np.deg2rad(rng.choice(np.arange(0, 360, 45), n_rows))
    x, y = np.round(10 * np.cos(angles), 6), np.round(10 * np.sin(angles), 6)
    success = (rng.random(n_rows) < 0.8).astype(float) * attempt
    labels = np.array(["TrialAttemp", "TrialSuccess", "x_sp", "y_sp", "RewardAmount"], dtype=object)
    data = np.empty((1, 5), dtype=object)
    for i, col in enumerate([attempt, success, x, y, success * 0.3]):
        data[0, i] = col.reshape(-1, 1)
    sio.savemat(beh / "remgs1.mat", {"Results": {"labels": labels, "data": data}})

    # events: trial start (4) then attempt (1) 200 ms later, times in ms
    starts = 1000.0 + np.arange(n_trials) * 3000.0
    codes = np.r_[np.full(n_trials, 4), np.full(n_trials, 1)]
    times = np.r_[starts, starts + 200.0]
    order = np.argsort(times)
    np.save(ev / "sync_event_codes.npy", np.c_[codes[order], times[order]])

    # spikes: Poisson background + direction-tuned burst 50-300 ms after attempt
    att_angles = angles[attempt == 1]
    duration = (starts[-1] + 3000.0) / 1000.0
    all_t, all_c = [], []
    for u in range(n_units):
        pref = rng.uniform(0, 2 * np.pi)
        t = list(rng.uniform(0, duration, rng.poisson(5 * duration)))
        for a_t, ang in zip((starts + 200.0) / 1000.0, att_angles):
            rate = 40 * np.exp(2 * (np.cos(ang - pref) - 1))
            t += list(a_t + rng.uniform(0.05, 0.3, rng.poisson(rate * 0.25)))
        all_t += t
        all_c += [u] * len(t)
    all_t = np.array(all_t)
    order = np.argsort(all_t)
    np.save(ks / "spike_times.npy", np.round(all_t[order] * sr).astype(np.uint64))
    np.save(ks / "spike_clusters.npy", np.array(all_c, dtype=np.int32)[order])
    counts = np.bincount(all_c, minlength=n_units)
    pd.DataFrame({
        "cluster_id": np.arange(n_units),
        "KSLabel": rng.choice(["good", "mua", "noise"], n_units, p=[0.5, 0.3, 0.2]),
        "group": "good",
        "depth": rng.uniform(0, 3840, n_units).round(1),
        "ch": rng.integers(0, 384, n_units),
        "n_spikes": counts,
        "ContamPct": rng.uniform(0, 20, n_units).round(2),
        "fr": (counts / duration).round(3),
    }).to_csv(ks / "cluster_info.tsv", sep="\t", index=False)

    cfg_path = Path(data_root) / "venni_20250731_SEF.toml"
    cfg_path.write_text(DEMO_CONFIG)
    return cfg_path
